/// List EVERY command name here. The `tauri-plugin` build-dep will auto-generate
/// `permissions/autogenerated/commands/<cmd>.toml` for each entry, exposing both
/// `allow-<cmd>` and `deny-<cmd>` permission identifiers.
///
/// The names must be valid Tauri command identifiers:
///   - lowercase ASCII letters / digits / underscores
///   - no leading/trailing underscore
///   - no uppercase, no hyphens (in command names — the plugin NAME may use hyphens)
const COMMANDS: &[&str] = &["ping"];

fn main() {
    tauri_plugin::Builder::new(COMMANDS)
        .android_path("android")
        .ios_path("ios")
        .global_api_script_path("./api-iife.js")
        .build();

    // If your plugin uses scoped permissions with a JSON schema, declare it:
    //   .global_scope_schema(schemars::schema_for!(MyScopeEntry))
}
